<?php declare(strict_types=1);session_start();if(empty($_SESSION['user'])){header('Location: login.php');exit;}$user=$_SESSION['user'];$config=require __DIR__.'/config.php';function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);if(($user['rol']??'')==='superadmin'){$orders=$pdo->query('SELECT id,codigo_pedido,cliente_nombre,cliente_telefono,monto_total,metodo_pago,estado_pago,estado_envio,created_at FROM pedidos ORDER BY id DESC LIMIT 100')->fetchAll();}else{$q=$pdo->prepare('SELECT id,codigo_pedido,cliente_nombre,cliente_telefono,monto_total,metodo_pago,estado_pago,estado_envio,created_at FROM pedidos WHERE tienda_id=? ORDER BY id DESC LIMIT 100');$q->execute([(int)($user['tienda_id']??0)]);$orders=$q->fetchAll();}}catch(Throwable $e){http_response_code(500);exit('No se pudieron cargar los pedidos.');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedidos</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0;color:#171717}main{max-width:1100px;margin:auto;padding:30px 20px}.card{background:#fff;padding:22px;border-radius:16px;margin:16px 0;overflow:auto}a{color:#886c42}table{width:100%;border-collapse:collapse;min-width:850px}th,td{text-align:left;padding:12px 8px;border-bottom:1px solid #eee}th{font-size:13px;color:#666}select,button{padding:8px;border:1px solid #ccc;border-radius:7px}button{background:#886c42;color:#fff;border:0;cursor:pointer}.detail{font-size:12px}</style></head><body><main><p><a href="panel.php">← Panel</a> · <a href="logout.php">Cerrar sesión</a></p><section class="card"><h1>Gestión de pedidos</h1><p>Pedidos disponibles según tus permisos.</p><?php if(!$orders):?><p>Aún no hay pedidos.</p><?php else:?><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Pago</th><th>Envío</th><th>Fecha</th><th>Guardar</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=h($o['codigo_pedido'])?></td><td><?=h($o['cliente_nombre'])?><br><span class="detail"><?=h($o['cliente_telefono'])?></span></td><td>S/ <?=h((string)$o['monto_total'])?><br><span class="detail"><?=h($o['metodo_pago'])?></span></td><td><form method="post" action="pedido-actualizar.php"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="estado_pago"><option value="pendiente_validacion" <?=$o['estado_pago']==='pendiente_validacion'?'selected':''?>>Pendiente</option><option value="aprobado" <?=$o['estado_pago']==='aprobado'?'selected':''?>>Aprobado</option><option value="rechazado" <?=$o['estado_pago']==='rechazado'?'selected':''?>>Rechazado</option></select></td><td><select name="estado_envio"><option value="pendiente" <?=$o['estado_envio']==='pendiente'?'selected':''?>>Pendiente</option><option value="recibido" <?=$o['estado_envio']==='recibido'?'selected':''?>>Recibido</option><option value="en_transito" <?=$o['estado_envio']==='en_transito'?'selected':''?>>En tránsito</option><option value="llego" <?=$o['estado_envio']==='llego'?'selected':''?>>Llegó</option><option value="entregado" <?=$o['estado_envio']==='entregado'?'selected':''?>>Entregado</option></select></td><td><?=h((string)$o['created_at'])?></td><td><button>Guardar</button></form></td></tr><?php endforeach;?></tbody></table><?php endif;?></section></main></body></html>
